import { createReadStream } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { link, mkdir, rename, rm, stat, writeFile } from 'node:fs/promises';
import type { Readable } from 'node:stream';
import { dirname, join, resolve, sep } from 'node:path';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import type { EnvironmentVariables } from '../config/environment.js';

/**
 * Object keys are generated by the server only: "<area>/<uuid>[.<ext>]", plus the compressed
 * copies of models, "clean/<uuid>.view.glb" and ".lite.glb".
 */
const KEY =
  /^((quarantine|clean)\/[0-9a-f-]{36}(\.[a-z0-9]{2,5})?|clean\/[0-9a-f-]{36}\.(view|lite)\.glb)$/;

function assertValidKey(key: string): void {
  if (!KEY.test(key))
    throw new Error(`Refusing unexpected storage key "${key}"`);
}

/**
 * Where file bytes live: a private directory (on the servers, a Docker volume that only the
 * API mounts, backed up encrypted off the server). Nothing is ever served from it directly:
 * every read goes through UploadsService.media and its access rules.
 */
export abstract class FileStorage {
  abstract put(key: string, data: Uint8Array): Promise<void>;
  abstract move(from: string, to: string): Promise<void>;
  abstract remove(key: string): Promise<void>;
  /** The bytes of a stored object, or null if it doesn't exist. */
  abstract open(
    key: string,
  ): Promise<{ stream: Readable; size: number } | null>;
}

@Injectable()
export class LocalDiskStorage extends FileStorage {
  private readonly root: string;

  constructor(config: ConfigService<EnvironmentVariables, true>) {
    super();
    this.root = resolve(config.get('UPLOAD_DIR', { infer: true }));
  }

  /**
   * Written under a temporary name, then linked into place: a reader never sees half a file,
   * a crash leaves no truncated one, and an existing key is never overwritten.
   */
  async put(key: string, data: Uint8Array): Promise<void> {
    const path = this.pathOf(key);
    await mkdir(dirname(path), { recursive: true });
    const partial = `${path}.${randomUUID()}.partial`;
    await writeFile(partial, data, { flag: 'wx' });
    try {
      await link(partial, path);
    } finally {
      await rm(partial, { force: true });
    }
  }

  async move(from: string, to: string): Promise<void> {
    const target = this.pathOf(to);
    await mkdir(dirname(target), { recursive: true });
    await rename(this.pathOf(from), target);
  }

  async remove(key: string): Promise<void> {
    await rm(this.pathOf(key), { force: true });
  }

  async open(key: string): Promise<{ stream: Readable; size: number } | null> {
    const path = this.pathOf(key);
    try {
      const { size } = await stat(path);
      return { stream: createReadStream(path), size };
    } catch {
      return null;
    }
  }

  private pathOf(key: string): string {
    assertValidKey(key);
    const path = resolve(join(this.root, key));
    if (!path.startsWith(this.root + sep))
      throw new Error('Path escapes the upload directory');
    return path;
  }
}
